<?php
declare(strict_types=1);use App\Support\Database;
return static function(Database $db):void{
 $db->execute("CREATE TABLE IF NOT EXISTS kyc_configurations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,country_id BIGINT UNSIGNED NOT NULL,form_id BIGINT UNSIGNED NULL,is_required TINYINT(1) NOT NULL DEFAULT 0,instructions TEXT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY kyc_country_version(country_id,version),INDEX kyc_country_active(country_id,is_active),CONSTRAINT fk_kyc_config_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_kyc_config_form FOREIGN KEY(form_id) REFERENCES dynamic_forms(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS kyc_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,configuration_id BIGINT UNSIGNED NOT NULL,configuration_version INT UNSIGNED NOT NULL,status ENUM('DRAFT','PENDING','UNDER_REVIEW','APPROVED','REJECTED','RESUBMISSION_REQUIRED') NOT NULL DEFAULT 'DRAFT',submitted_at DATETIME NULL,reviewed_at DATETIME NULL,reviewed_by_user_id BIGINT UNSIGNED NULL,rejection_reason TEXT NULL,resubmission_message TEXT NULL,admin_notes TEXT NULL,approved_at DATETIME NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY kyc_public(public_id),INDEX kyc_user_country(user_id,country_id,status),INDEX kyc_queue(status,country_id,submitted_at),CONSTRAINT fk_kyc_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_kyc_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_kyc_config FOREIGN KEY(configuration_id) REFERENCES kyc_configurations(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS kyc_submission_values (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kyc_submission_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,field_label VARCHAR(255) NOT NULL,value_text TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY kyc_value(kyc_submission_id,field_key),CONSTRAINT fk_kyc_value_submission FOREIGN KEY(kyc_submission_id) REFERENCES kyc_submissions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS kyc_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kyc_submission_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,storage_path VARCHAR(255) NOT NULL,original_filename VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX kyc_doc_submission(kyc_submission_id),CONSTRAINT fk_kyc_doc_submission FOREIGN KEY(kyc_submission_id) REFERENCES kyc_submissions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS kyc_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kyc_submission_id BIGINT UNSIGNED NOT NULL,actor_user_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,user_message TEXT NULL,private_note TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX kyc_events_submission(kyc_submission_id,created_at),CONSTRAINT fk_kyc_event_submission FOREIGN KEY(kyc_submission_id) REFERENCES kyc_submissions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS withdrawal_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,description TEXT NULL,instructions TEXT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,minimum_amount_minor BIGINT UNSIGNED NOT NULL,maximum_amount_minor BIGINT UNSIGNED NULL,fee_type ENUM('NONE','FIXED','PERCENTAGE') NOT NULL DEFAULT 'NONE',fee_value DECIMAL(20,8) NOT NULL DEFAULT 0,estimated_processing_time VARCHAR(190) NULL,form_id BIGINT UNSIGNED NULL,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY withdrawal_method_public(public_id),UNIQUE KEY withdrawal_method_slug(slug),CONSTRAINT fk_withdrawal_method_form FOREIGN KEY(form_id) REFERENCES dynamic_forms(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS withdrawal_method_countries (withdrawal_method_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(withdrawal_method_id,country_id),CONSTRAINT fk_wmc_method FOREIGN KEY(withdrawal_method_id) REFERENCES withdrawal_methods(id) ON DELETE RESTRICT,CONSTRAINT fk_wmc_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS withdrawal_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,reference VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,wallet_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,currency_code CHAR(3) NOT NULL,withdrawal_method_id BIGINT UNSIGNED NOT NULL,method_snapshot JSON NOT NULL,requested_amount_minor BIGINT UNSIGNED NOT NULL,fee_minor BIGINT UNSIGNED NOT NULL,payout_amount_minor BIGINT UNSIGNED NOT NULL,reserved_amount_minor BIGINT UNSIGNED NOT NULL,reservation_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','UNDER_REVIEW','APPROVED','PROCESSING','PAID','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING',submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,reviewed_by_user_id BIGINT UNSIGNED NULL,rejection_reason TEXT NULL,admin_notes TEXT NULL,payout_reference VARCHAR(190) NULL,completed_ledger_transaction_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY withdrawal_public(public_id),UNIQUE KEY withdrawal_reference(reference),UNIQUE KEY withdrawal_ledger(completed_ledger_transaction_id),INDEX withdrawal_queue(status,country_id,submitted_at),CONSTRAINT fk_wr_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_wr_wallet FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,CONSTRAINT fk_wr_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_wr_method FOREIGN KEY(withdrawal_method_id) REFERENCES withdrawal_methods(id) ON DELETE RESTRICT,CONSTRAINT fk_wr_reservation FOREIGN KEY(reservation_id) REFERENCES wallet_reservations(id) ON DELETE RESTRICT,CONSTRAINT fk_wr_ledger FOREIGN KEY(completed_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
};
